<?php
declare(strict_types=1);
use App\Http\Controllers\Classrooms\{ClassroomController,ClassroomStatusController,ClassroomHomeroomController,ClassroomMemberController,ClassroomMemberMoveController,ClassroomLegacyMappingController,ClassroomCopyController,ClassroomPromotionController,ClassroomGuideController}; use Illuminate\Support\Facades\Route;
Route::middleware(['auth','active','force-password-change'])->prefix('classrooms')->name('classrooms.')->group(function(){
 Route::get('/',[ClassroomController::class,'index'])->name('index'); Route::get('/create',[ClassroomController::class,'create'])->name('create'); Route::post('/',[ClassroomController::class,'store'])->name('store'); Route::get('/guide',ClassroomGuideController::class)->name('guide');
