 Route::get('/promotions',[ClassroomPromotionController::class,'form'])->name('promotions.form'); Route::post('/promotions/preview',[ClassroomPromotionController::class,'preview'])->name('promotions.preview'); Route::post('/promotions/confirm',[ClassroomPromotionController::class,'confirm'])->name('promotions.confirm'); Route::get('/promotions/{batch}',[ClassroomPromotionController::class,'result'])->name('promotions.result');
